import{_ as r,a as e,c as a,ac as o}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 60 节：尺度应使生活可持续至62 小过：在有限处适度加厚","description":"从巽兑的沟通读到涣节的尺度、中孚的信实与既济未济的开放结尾，逐爻核对古籍。","frontmatter":{"title":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 60 节：尺度应使生活可持续至62 小过：在有限处适度加厚","description":"从巽兑的沟通读到涣节的尺度、中孚的信实与既济未济的开放结尾，逐爻核对古籍。","splitFrom":"life/personal/yijing/hexagrams-57-64.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济","summary":"从巽兑的沟通读到涣节的尺度、中孚的信实与既济未济的开放结尾，逐爻核对古籍。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 57 巽：温和进入，也须明确行动至59 涣：散开阻滞，再寻共同依托","link":"/life/personal/yijing/hexagrams-57-64-part-01"},"next":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 63 既济：完成之后仍要照料至读完六十四卦之后","link":"/life/personal/yijing/hexagrams-57-64-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 57 巽：温和进入，也须明确行动至59 涣：散开阻滞，再寻共同依托","link":"/life/personal/yijing/hexagrams-57-64-part-01"},"next":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 63 既济：完成之后仍要照料至读完六十四卦之后","link":"/life/personal/yijing/hexagrams-57-64-part-03"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-57-64-part-02.md","filePath":"life/personal/yijing/hexagrams-57-64-part-02.md"}'),n={name:"life/personal/yijing/hexagrams-57-64-part-02.md"};function d(s,t,i,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="六十四卦详读-五十七至六十四-巽、兑、涣、节、中孚、小过、既济、未济-·-60-节-尺度应使生活可持续至62-小过-在有限处适度加厚" tabindex="-1">六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 60 节：尺度应使生活可持续至62 小过：在有限处适度加厚 <a class="header-anchor" href="#六十四卦详读-五十七至六十四-巽、兑、涣、节、中孚、小过、既济、未济-·-60-节-尺度应使生活可持续至62-小过-在有限处适度加厚" aria-label="Permalink to &quot;六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 60 节：尺度应使生活可持续至62 小过：在有限处适度加厚&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-57-64">返回分篇目录</a></p><p>本篇完成六十四卦的最后一组。每卦先列<strong>经文原文</strong>，再列现代简释；<strong>大象</strong>来自《象传》，主要古注依据为王弼注、孔颖达疏《周易正义》。引文保留古代字形与占筮判断，现代概括不作为预测方法。个别电子本文字不同，采用哪种写法会就地注明。</p><p>这组可从四条线索进入：巽与兑的传达和相悦，涣与节的散释和限制，中孚与小过的信实和分寸，既济与未济的完成和未完成。不要先给整卦贴上“好卦、坏卦”标签，再忽略其中相反的爻辞。</p><h2 id="gua-60" tabindex="-1">60 节：尺度应使生活可持续 <a class="header-anchor" href="#gua-60" aria-label="Permalink to &quot;60 节：尺度应使生活可持续 {#gua-60}&quot;">​</a></h2><p><strong>卦符：䷻｜上卦坎 ☵（水），下卦兑 ☱（泽）。</strong> 泽容水而有界，节由分节、限度展开到制度和行为尺度。</p><p><strong>卦辞原文：</strong></p><blockquote><p>節：亨。苦節不可貞。</p></blockquote><p><strong>白话概括：</strong> 适当节制能够通达，过度刻苦的限制不能作为恒常正道。《正义》直言苦节会使人不能承受；《彖传》更以“不伤财、不害民”检验制度。这使节不是越严越好，而是检验限度是否适当。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>不出戶庭，无咎。</td><td>在应慎密、尚未宜行动之时留在户内，可以无过；其依据是知通塞。</td></tr><tr><td>九二</td><td>不出門庭，凶。</td><td>同样不出门，却因错过应行动之时而凶；只模仿行为外形，不能得到同一结果。</td></tr><tr><td>六三</td><td>不節若，則嗟若，无咎。</td><td>不知节制而后叹息；《小象》“又谁咎”提示此处可理解为无可归咎他人，不是行为完全无过。</td></tr><tr><td>六四</td><td>安節，亨。</td><td>安于合适的尺度，不需不断与自己或他人对抗；可持续的节制较易通行。</td></tr><tr><td>九五</td><td>甘節，吉；往有尚。</td><td>节制使人能接受并受益，如甘美而不苦迫；居中制定尺度，也要承担示范责任。</td></tr><tr><td>上六</td><td>苦節，貞凶，悔亡。</td><td>节制走到苦迫极端；《正义》将凶解释为施于他人难以承受，将悔亡解释为自修俭约，两种对象须分清。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>澤上有水，節；君子以制數度，議德行。</p></blockquote><p><strong>大象解释：</strong> 制定数量、礼度，并讨论德行与任用的适宜。古代数度包含等级礼制；现代可讨论公开标准和适用范围，同时审查公平性。</p><p><strong>整体读法与误区：</strong> 初九和九二的相反结果，是学习《易》“时、位”关系的简明例子：同样待在家中，条件不同，判断也不同。日常作息、开支、学习计划可以借节思考底线与余地，评估是否损伤健康、关系和基本生活。把节解释成极端节食、无休工作或强迫清贫，恰好忽略卦辞先提出的“苦节不可贞”。</p><p><strong>经传对读：</strong>“安节、甘节、苦节”不仅评价限制的数量，也写实行限制时的感受和效果。初九、九二则把时间条件加入：同一条规则换了时机可能变成阻碍。六三的叹息还提醒没有节制的代价由谁承担。把这些词与《彖传》的“不伤财、不害民”相对照，就能同时检验个人习惯和集体制度；若一项规则让所有人长期难以承受，应重新审查规则，而不只责怪执行者意志不足。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%AF%80" target="_blank" rel="noopener noreferrer">《周易·节》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/06%E7%AF%80" target="_blank" rel="noopener noreferrer">《周易正义》卷六·节</a>。</p><h2 id="gua-61" tabindex="-1">61 中孚：诚信要有可回应的实质 <a class="header-anchor" href="#gua-61" aria-label="Permalink to &quot;61 中孚：诚信要有可回应的实质 {#gua-61}&quot;">​</a></h2><p><strong>卦符：䷼｜上卦巽 ☴（风），下卦兑 ☱（泽）。</strong>“孚”在传注传统中多按信解释；《正义》以信发于中说明卦名，并由内柔、二五刚中解释卦体。</p><p><strong>卦辞原文：</strong></p><blockquote><p>中孚：豚魚吉，利涉大川，利貞。</p></blockquote><p><strong>白话概括：</strong> 诚信能及于微小幽隐之物，可以共同渡险，但仍须合于正。《正义》将豚与鱼分解为兽、鱼来说明惠及微隐；围绕“豚鱼”的词义还有其他讨论。此处呈现的是传统伦理解释，不能据之声称心念可直接影响动物或天气。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>虞吉，有它不燕。</td><td>《正义》将“虞”释为专一，“燕”为安；信任初建却另怀意图，关系难安。其余训释可另作比较。</td></tr><tr><td>九二</td><td>鳴鶴在陰，其子和之，我有好爵，吾與爾靡之。</td><td>鹤在幽处鸣而幼鹤相和，美好之物愿共享；“爵”可涉酒器或爵位，古注偏向不私权利。</td></tr><tr><td>六三</td><td>得敵，或鼓或罷，或泣或歌。</td><td>受相对者牵动，进退、哭歌反复，显出内在缺乏稳定；“敌”也有匹敌、对待之义。</td></tr><tr><td>六四</td><td>月幾望，馬匹亡，无咎。</td><td>月将满而失去马匹之伴，古注解释为不与同类争、转向正当关系；此从《正义》“几望”，电子本另见“既望”。</td></tr><tr><td>九五</td><td>有孚攣如，无咎。</td><td>信实相系不绝，承担主事责任者须持续维系可信行为；“攣”是牵系，不等于控制人身。</td></tr><tr><td>上九</td><td>翰音登于天，貞凶。</td><td>声音高扬而超过实质，难以长久；“翰音”有鸟鸣的背景，切忌把高声宣称当成可信证据。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>澤上有風，中孚；君子以議獄緩死。</p></blockquote><p><strong>大象解释：</strong> 审议案件，对死刑保持缓慎，古注重在体察过失与可恕之情。诚信在此引出认真理解他人，而不是凭主观相信跳过证据。</p><p><strong>整体读法与误区：</strong> 九二的相和与上九的高音形成对照：一种有回应、有共享，一种只把声音抬高。现代可借此检视承诺是否兑现、信息是否可核实、对方能否自由表达疑虑。中孚有“利贞”，表明相信某人并不能使不正当的事变正当；“诚心就能感应万物”的神秘化读法，也远超所核文字能证明的范围。</p><p><strong>经传对读：</strong> 九二借声音写相应，六三借哭歌写动摇，上九借高音写难久，声音相似却有三种关系状态。六四放下争逐、九五维系承诺又补充了行动层面的证据。阅读中可先问信从哪里来、由什么行为维持，再讨论它能否使人合作；否则“诚”容易被写成无法验证的内心自我宣称。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B8%AD%E5%AD%9A" target="_blank" rel="noopener noreferrer">《周易·中孚》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/06%E4%B8%AD%E5%AD%9A" target="_blank" rel="noopener noreferrer">《周易正义》卷六·中孚</a>。</p><h2 id="gua-62" tabindex="-1">62 小过：在有限处适度加厚 <a class="header-anchor" href="#gua-62" aria-label="Permalink to &quot;62 小过：在有限处适度加厚 {#gua-62}&quot;">​</a></h2><p><strong>卦符：䷽｜上卦震 ☳（雷），下卦艮 ☶（山）。</strong> 小过之“过”有超过常度的意义。《正义》特别反对只把卦名理解成犯小错误，主要解释为小事上做得稍厚。</p><p><strong>卦辞原文：</strong></p><blockquote><p>小過：亨。利貞。可小事，不可大事。飛鳥遺之音，不宜上宜下，大吉。</p></blockquote><p><strong>白话概括：</strong> 可在较小事务中适度超过常态，仍以正当为限；当前不宜承担宏大作为。飞鸟之象提醒下降求安，古注也将它纳入君臣尊卑，但现代可以先保留“与能力、处境相称”的问题，不照搬政治服从关系。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>飛鳥以凶。</td><td>初始即像鸟向高处飞去，超出适当范围而有凶；不是说现实乘机或见鸟必然不利。</td></tr><tr><td>六二</td><td>過其祖，遇其妣；不及其君，遇其臣；无咎。</td><td>祖妣、君臣表现不同相遇位置；古注强调不越君位，今读需识别其中的宗法政治结构。</td></tr><tr><td>九三</td><td>弗過防之，從或戕之，凶。</td><td>防范不足，可能被随后而来的力量伤害；“戕”读 qiāng，指伤害，警戒针对所处危险条件。</td></tr><tr><td>九四</td><td>无咎，弗過遇之。往厲必戒，勿用永貞。</td><td>不过分而能相遇，前行仍要戒惧；眼前权宜不宜永远固守，“贞”不可一律替换为硬坚持。</td></tr><tr><td>六五</td><td>密雲不雨，自我西郊，公弋取彼在穴。</td><td>云密而雨未成，公以系绳之箭取穴中之物；“弋”是射法，表现力量与目标需相合。</td></tr><tr><td>上六</td><td>弗遇過之，飛鳥離之，凶，是謂災眚。</td><td>没有恰当相遇而越过，飞鸟遭罹其害；“离”可按遭罹理解，过高无归成为结尾的警戒。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>山上有雷，小過；君子以行過乎恭，喪過乎哀，用過乎儉。</p></blockquote><p><strong>大象解释：</strong> 行为稍多恭敬、丧礼稍多哀情、用度稍多俭约，是在具体小事上加厚。古注将其放在矫正风俗的情境中，不是永久鼓励任何形式的过度。</p><p><strong>整体读法与误区：</strong> 与节连读可避免误会：小过讲有时稍过，节明确反对苦节；二者共同要求分辨时宜。现代可讨论为风险增加适量余地、为他人多留一点礼貌，而不能把过劳、过度哀伤或全面退缩美化为德行。大象的“过”有范围，卦辞也明写“可小事，不可大事”，不能略去这些限定只留下“突破极限”。</p><p><strong>经传对读：</strong> 卦辞和初、上两爻都用飞鸟，首尾相照，强调所处高度与可安身之地的关系。中间的祖妣、君臣与公弋又把尺度带入人间秩序。将两类意象分开再合读，才能看清古注如何由鸟的上下飞行转出伦理判断，也能意识到这种解释并不是鸟类行为本身直接证明了政治等级。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E9%81%8E" target="_blank" rel="noopener noreferrer">《周易·小过》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/06%E5%B0%8F%E9%81%8E" target="_blank" rel="noopener noreferrer">《周易正义》卷六·小过</a>。</p>',43)])])}const k=r(n,[["render",d]]);export{c as __pageData,k as default};
